{
  "task_summary": "Predict whether an NHANES participant has elevated blood lead, favoring features that reflect durable exposure risk rather than survey-wave or demographic shortcuts.",
  "scores": [
    {
      "feature_id": 0,
      "score": 0.05,
      "rationale": "Survey year is highly domain-specific and likely captures changing background lead exposure and measurement era, so it is a brittle shortcut for OOD generalization."
    },
    {
      "feature_id": 1,
      "score": 0.22,
      "rationale": "Country of birth may correlate with lifetime environmental exposure differences, but it is coarse and can act as a demographic/domain proxy rather than a stable causal signal."
    },
    {
      "feature_id": 2,
      "score": 0.58,
      "rationale": "Education is a reasonably stable socioeconomic indicator tied to housing, occupation, and environmental risk, making it moderately useful across domains."
    },
    {
      "feature_id": 3,
      "score": 0.86,
      "rationale": "Age is a strong, semantically stable predictor because lead burden and historical exposure opportunities vary systematically over the life course and across birth cohorts."
    },
    {
      "feature_id": 4,
      "score": 0.41,
      "rationale": "Gender can reflect stable differences in occupation and exposure patterns, but it is also a broad demographic shortcut with limited specificity."
    },
    {
      "feature_id": 5,
      "score": 0.27,
      "rationale": "Marital status may weakly track household and socioeconomic context, but it is indirect, age-confounded, and not a robust exposure mechanism."
    },
    {
      "feature_id": 6,
      "score": 0.24,
      "rationale": "Race/ethnicity may correlate with structural exposure disparities, but it is a sensitive proxy that risks encoding domain-specific social patterns rather than transportable causal information."
    }
  ]
}

